package fixture

import "testing"

func TestCapitalize(t *testing.T) {
	if got := Capitalize("hello world"); got != "Hello World" {
		t.Fatalf("Capitalize = %q, want Hello World", got)
	}
	if got := Capitalize(""); got != "" {
		t.Fatalf("Capitalize(empty) = %q", got)
	}
}
